    private static void patch(ClassNode node){MethodNode finish=method(node,"finishManorFiveCast");InsnList first=new InsnList();first.add(new VarInsnNode(ALOAD,0));first.add(new MethodInsnNode(INVOKESTATIC,"net/farmingtales/ftboss/dandanmotion/MotionServer","finish","(Lnet/farmingtales/ftboss/entity/EasterBossEntity;)V",false));finish.instructions.insert(first);MethodNode sync=method(node,"syncCombatAnimation");MethodInsnNode set=(MethodInsnNode)Arrays.stream(sync.instructions.toArray()).filter(value->value instanceof MethodInsnNode call&&call.owner.equals("net/minecraft/network/syncher/SynchedEntityData")&&call.name.equals("set")).findFirst().orElseThrow();AbstractInsnNode firstStore=set;for(int count=0;count<4;){firstStore=firstStore.getPrevious();if(firstStore.getOpcode()>=0)count++;}InsnList carry=new InsnList();carry.add(new VarInsnNode(ALOAD,0));carry.add(new VarInsnNode(ALOAD,5));carry.add(new MethodInsnNode(INVOKESTATIC,"net/farmingtales/ftboss/dandanmotion/MotionServer","carry","(Lnet/farmingtales/ftboss/entity/EasterBossEntity;Lnet/minecraft/nbt/CompoundTag;)V",false));sync.instructions.insertBefore(firstStore,carry);}
    static String instructionFingerprint(MethodNode method){if(!method.tryCatchBlocks.isEmpty())throw new IllegalStateException("Unexpected lifecycle exception handlers");MethodNode copy=new MethodNode(method.access,method.name,method.desc,method.signature,method.exceptions.toArray(String[]::new));method.accept(copy);for(AbstractInsnNode instruction:copy.instructions.toArray())if(instruction instanceof FrameNode||instruction instanceof LineNumberNode)copy.instructions.remove(instruction);Set<LabelNode> targets=Collections.newSetFromMap(new IdentityHashMap<>());for(AbstractInsnNode instruction:copy.instructions.toArray()){if(instruction instanceof JumpInsnNode branch)targets.add(branch.label);if(instruction instanceof TableSwitchInsnNode table){targets.add(table.dflt);targets.addAll(table.labels);}if(instruction instanceof LookupSwitchInsnNode table){targets.add(table.dflt);targets.addAll(table.labels);}}for(AbstractInsnNode instruction:copy.instructions.toArray())if(instruction instanceof LabelNode label&&!targets.contains(label))copy.instructions.remove(label);org.objectweb.asm.util.Textifier text=new org.objectweb.asm.util.Textifier();copy.instructions.accept(new org.objectweb.asm.util.TraceMethodVisitor(text));String canonical=method.access+String.valueOf((char)10)+method.name+String.valueOf((char)10)+method.desc+String.valueOf((char)10)+method.signature+String.valueOf((char)10)+method.exceptions+String.valueOf((char)10)+text.getText();try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException failure){throw new IllegalStateException(failure);}}
    public static void main(String[] arguments)throws Exception{try(ZipFile jar=new ZipFile(arguments[0])){Map<String,String> expected=new LinkedHashMap<>();for(boolean reverse:new boolean[]{false}){ClassNode node=read(jar);NativeManorMixinPlugin plugin=new NativeManorMixinPlugin();for(String mixin:List.of("NativeManorRaidMixin"))plugin.postApply("net.farmingtales.ftboss.entity.EasterBossEntity",node,"net.farmingtales.ftboss.mixin."+mixin,null);for(String name:List.of("syncCombatAnimation","finishManorFiveCast")){String hash=instructionFingerprint(method(node,name));String previous=expected.putIfAbsent("before:"+name,hash);if(previous!=null&&!previous.equals(hash))throw new AssertionError("Original mixin order changes scoped preimage");System.out.println("reverse="+reverse+";before:"+name+"="+hash);}patch(node);for(String name:List.of("syncCombatAnimation","finishManorFiveCast")){String hash=instructionFingerprint(method(node,name));String previous=expected.putIfAbsent("after:"+name,hash);if(previous!=null&&!previous.equals(hash))throw new AssertionError("Original mixin order changes scoped postimage");System.out.println("reverse="+reverse+";after:"+name+"="+hash);}ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_MAXS);node.accept(writer);Files.write(Path.of(arguments[1]+"-"+reverse+".class"),writer.toByteArray());}System.out.println("failures=0;exactActualBossMixinTarget=NativeManorRaidMixin;NativeAnimationEmitterMixinTargetsSpellVisualsAndSignatureSpellOnly=true;scope=ClassNodeOnlyNoGameplayOrProductChange");}}
